  ercole:{...c1.ercole}, gina:{...c1.gina, x:260}, toto:{...c1.toto}, ciccio:{...c1.ciccio}, marisa:{...c1.marisa}, baffo:{...c1.baffo, gone:()=>F().baffoTaken}, rocky:{...c1.rocky}, rino:{...c1.rino},
  liborio:{room:'campanile', x:300, name:['Don Liborio','Father Liborio'], kind:'m', col:'#f1faee', look:{hair:'bald',hairColor:'#eeeeee',skin:'#eab48a',glasses:true,outfit:'#1d1d24',pants:'#1d1d24',top:'jacket',bottom:'pants',phys:'belly'}},
